using System;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEngine;
namespace LegacyGwent.LadyLakePremium.Acceptance {
public static class PremiumPoseCapture {
const string Root="Assets/Experiments/LadyLakePremium";
public static void EnvironmentOnly(){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(Root+"/Environment/Environment.prefab");var go=UnityEngine.Object.Instantiate(prefab);var cg=new GameObject("Environment camera");var cam=cg.AddComponent<Camera>();cam.enabled=false;cam.cullingMask=1<<29;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.02f,.05f,.06f);cam.fieldOfView=35;cam.transform.position=new Vector3(0,0,-11.5f);try{foreach(var t in go.GetComponentsInChildren<Transform>(true))t.gameObject.layer=29;string folder=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../../../work/LadyLakePremium/poses"));Directory.CreateDirectory(folder);LegacyGwent.LadyLakeLab.Acceptance.LadyLakeAcceptance.Capture(cam,Path.Combine(folder,"environment.png"),714,1024);}finally{UnityEngine.Object.DestroyImmediate(go);UnityEngine.Object.DestroyImmediate(cg);}} public static void Run(){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(Root+"/Model/FigureRig.prefab");if(!prefab)throw new Exception("Model prefab not built yet");var go=UnityEngine.Object.Instantiate(prefab);go.hideFlags=HideFlags.HideAndDontSave;var camGO=new GameObject("Premium pose camera");camGO.hideFlags=HideFlags.HideAndDontSave;var cam=camGO.AddComponent<Camera>();cam.enabled=false;cam.cullingMask=1<<29;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.04f,.08f,.09f);cam.fieldOfView=35;cam.nearClipPlane=.1f;cam.farClipPlane=60;cam.transform.position=new Vector3(0,0,-11.5f);string folder=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../../../work/LadyLakePremium/poses"));Directory.CreateDirectory(folder);try{foreach(var t in go.GetComponentsInChildren<Transform>(true))t.gameObject.layer=29;foreach(var a in go.GetComponentsInChildren<Animator>(true)){a.Rebind();a.Update(0);a.enabled=true;}foreach(float time in new[]{0f,2.6f,3.2f,4.5f,5.6f,7f,9.5f,11.98f}){foreach(var a in go.GetComponentsInChildren<Animator>(true)){var clip=a.runtimeAnimatorController==null?null:a.runtimeAnimatorController.animationClips.FirstOrDefault(c=>c.name.Contains("Loop"));if(clip!=null){a.Play("Loop",0,time/clip.length);a.Update(0f);}}foreach(var m in go.GetComponentsInChildren<Assets.Script.DynamicCards.DynamicCardAnimatedMaterialProperty>(true))m.ApplyNow();LegacyGwent.LadyLakeLab.Acceptance.LadyLakeAcceptance.Capture(cam,Path.Combine(folder,"front-"+time.ToString("F2",System.Globalization.CultureInfo.InvariantCulture)+".png"),714,1024);}cam.transform.position=new Vector3(8,0,-8);cam.transform.LookAt(Vector3.zero);LegacyGwent.LadyLakeLab.Acceptance.LadyLakeAcceptance.Capture(cam,Path.Combine(folder,"side.png"),900,1024);
File.WriteAllLines(Path.Combine(folder,"hierarchy.txt"),go.GetComponentsInChildren<Transform>(true).Select(t=>AnimationUtility.CalculateTransformPath(t,go.transform)+" local="+t.localPosition.ToString("F4")+" scale="+t.localScale.ToString("F4")+" world="+t.position.ToString("F4")).ToArray());
var rows=go.GetComponentsInChildren<SkinnedMeshRenderer>(true).Select(s=>s.name+" vertices="+s.sharedMesh.vertexCount+" bones="+s.bones.Length+" bounds="+s.bounds+" materials="+string.Join(",",s.sharedMaterials.Select(m=>m==null?"NULL":m.name+" / "+m.shader.name))).ToArray();File.WriteAllLines(Path.Combine(folder,"meshes.txt"),rows);
}finally{UnityEngine.Object.DestroyImmediate(go);UnityEngine.Object.DestroyImmediate(camGO);}}
}}

